export async function managementPanel(c){
 const {api,esc,fmt,form,input}=c,a=await api('management');
 const mf=(action,fields,button)=>form(action,fields,button,'data-management="true"');
 const target=input('Hesap no','target','number','','required min="1"');
 const roomSelect='<label>Oda<select name="room">'+a.rooms.map(r=>`<option value="${esc(r.id)}">${esc(r.id)}${r.closed?' · Kapalı':''}</option>`).join('')+'</select></label>';
 return `<h2>Yönetici Paneli</h2><p class="subtle">Canlı oyuncular ve odalar 5 saniyede bir yenilenir. İşlemler denetim kaydına yazılır.</p><label class="admin-search">Canlı oyuncu ara<input type="search" data-admin-player-filter placeholder="İsim, hesap no veya oda"></label><div id="management-live">${managementLive(a,c)}</div>
 <div class="admin-tabs"><a href="#admin-room-board">Tüm odalar</a><a href="#admin-create-room">Yeni oda</a><a href="#admin-boost">Boost / hız</a><a href="#admin-mute">Sohbet banı</a></div>
 <h3 id="admin-room-board">Tüm odalar · ${a.rooms.length}</h3><label class="admin-search">Oda ara<input type="search" data-admin-room-filter placeholder="Ör. FFA-12 veya BOOST"></label><div class="admin-table-scroll"><table class="data-table"><thead><tr><th>ODA</th><th>GİRİŞ</th><th>AKTİF</th><th>İZLEYİCİ</th><th>KALAN</th><th>TUR ÖDÜLÜ</th><th>BAŞLANGIÇ</th><th>HIZ / BOOST</th></tr></thead><tbody id="management-room-rows">${managementRoomRows(a,c)}</tbody></table></div>
 <section class="sub-card" id="admin-create-room"><h3>Yeni oda aç</h3>${mf('createRoom',input('Oda adı','room','text','','required maxlength="24"')+'<label>Oda türü<select name="mode"><option value="ffa">Normal FFA</option><option value="boost">Boost</option><option value="special">Bonus Gold</option><option value="nogold">Goldsuz</option></select></label>'+input('Her turun süresi · dakika','minutes','number','60','required min="1" max="1440"')+input('Başlangıç ödülü · Gold','basePrize','number','50000','required min="0" max="100000000"'),'Odayı aç')}</section>
 <section class="sub-card"><h3>Odaya süre ekle</h3>${mf('addTime',roomSelect+input('Eklenecek dakika','minutes','number','10','required min="1" max="1440"'),'Aktif tura süre ekle')}<p class="subtle">Oyuncular, skorlar ve ödül korunur. Ek süre sonraki tura taşınmaz.</p></section>
 <section class="sub-card" id="admin-boost"><h3>Odaya özel Boost ve kontrol hızları</h3>${mf('roomBoost',roomSelect+input('Gold hız çarpanı · 1 = normal','goldRate','number','1','required min="1" max="50"')+input('Yem atma aralığı · ms (normal 90)','feedMs','number','90','required min="50" max="1000"')+input('Bölünme aralığı · ms (normal 80)','splitMs','number','80','required min="50" max="1000"')+input('Boost süresi · dakika (0 = süresiz)','minutes','number','10','required min="0" max="10080"'),'Odaya uygula')}${mf('roomBoost',roomSelect+'<input type="hidden" name="goldRate" value="1"><input type="hidden" name="feedMs" value="90"><input type="hidden" name="splitMs" value="80"><input type="hidden" name="minutes" value="0">','Boost kapat · normal hız')}<p class="subtle">Aralık küçüldükçe işlem hızlanır. Gold çarpanı aynı sürede harcanan Gold ve eklenen kütleyi artırır; ücretsiz Gold vermez. Gold 1, yem 90, bölünme 80 ile normal hıza dön. Artırılmış hızlarda ekran kenarları saydam sarı görünür. Süre bitince normal hız geri gelir.</p></section>
 <section class="sub-card"><h3>Oda ödülüne ekle</h3><p>Yalnızca bu turun ödülünü artırır; sonraki tur başlangıç ödülünü değiştirmez.</p>${mf('reward',roomSelect+input('Eklenecek ödül · Gold','amount','number','50000','required min="1" max="100000000"')+input('İşlem nedeni','reason','text','','required maxlength="200"'),'Oda ödülüne ekle')}</section>
 <div class="profile-columns"><section class="sub-card"><h3>Oda ayarları</h3>${mf('room',roomSelect+input('Yeni turların başlangıç ödülü','basePrize','number','50000','required min="0" max="100000000"')+input('Bu turun ödülüne ekle','extraPrize','number','0','required min="0" max="100000000"')+'<label>Giriş durumu<select name="closed"><option value="false">Açık</option><option value="true">Yeni girişlere kapalı</option></select></label>','Oda ayarlarını kaydet')}<p class="subtle">Süreler oda boşken de devam eder. Kapalı oda mevcut oyuncuları oyundan çıkarmaz.</p></section>
 <section class="sub-card"><h3>Turu elle bitir</h3>${mf('finishRoom',roomSelect,'Kazananı belirle ve yeni tura geç')}<h3>Genel duyuru</h3>${mf('announce','<label>Duyuru<textarea name="text" required maxlength="300"></textarea></label>','Tüm odalara duyur')}</section></div>
 <section class="sub-card"><h3>Skor ekle</h3><p>Hesap numarasıyla odada oynayan oyuncuya kütle ekler. Parça başına 220.084 ve toplam 5.500.000 sınırı korunur; Gold harcanmaz.</p>${mf('score',target+input('Eklenecek skor / kütle','amount','number','10000','required min="1" max="5500000"')+input('İşlem nedeni','reason','text','','required maxlength="200"'),'Oyuncuya skor ekle')}</section>
 <div class="profile-columns"><section class="sub-card"><h3>Gold / Bonus düzenle</h3>${mf('wallet',target+'<label>Bakiye<select name="wallet"><option value="gold">Gold</option><option value="bonus">Bonus Gold</option></select></label>'+input('Tutar (eksi değer düşürür)','amount','number','10000','required min="-100000000" max="100000000"')+input('İşlem nedeni','reason','text','','required maxlength="200"'),'Bakiyeyi güncelle')}</section>
 <section class="sub-card"><h3>Premium yönetimi</h3>${mf('premium',target+input('Gün (0 = Premium kaldır)','days','number','7','required min="0" max="365"'),'Premium uygula')}</section></div>
 <div class="profile-columns"><section class="sub-card" id="admin-mute"><h3>Süreli sohbet banı</h3>${mf('mute',target+input('Saat (0 = susturmayı kaldır)','hours','number','1','required min="0" max="8760"'),'Susturmayı uygula')}<h3>Oyundan çıkar</h3>${mf('kick',target,'Bağlantıyı kapat')}</section>
 <section class="sub-card"><h3>Tek kullanımlık PIN üret</h3>${mf('pin','<label>Tür<select name="kind"><option value="gold">Gold</option><option value="premium">Premium gün</option></select></label>'+input('Miktar / gün','amount','number','10000','required min="1" max="100000000"'),'PIN oluştur')}<p class="subtle">Kod yalnızca oluşturulduğunda gösterilir. Yönetici işlemleri denetim kaydına yazılır.</p></section></div>
 <h3>Oyuncular · son 200 hesap</h3><table class="data-table"><thead><tr><th>HESAP</th><th>İSİM</th><th>GOLD</th><th>BONUS</th><th>DURUM</th></tr></thead><tbody>${a.users.map(u=>`<tr><td>#${u.id}</td><td>${esc(u.name)}</td><td>${fmt(u.gold)}</td><td>${fmt(u.bonus)}</td><td>${u.bannedUntil>Date.now()?'Kısıtlı':u.mutedUntil>Date.now()?'Susturuldu':u.role==='admin'?'Yönetici':'Oyuncu'}</td></tr>`).join('')}</tbody></table>
 <h3>Oyuncu şikayetleri</h3>${a.reports.map(r=>`<section class="sub-card"><b>#${r.id} · #${r.reporter} → #${r.target} · ${esc(r.status)}</b><p>${esc(r.text)}</p>${mf('reportStatus','<input type="hidden" name="target" value="'+r.id+'"><label>Durum<select name="status"><option>Açık</option><option>İnceleniyor</option><option>Çözüldü</option></select></label>','Durumu kaydet')}</section>`).join('')||'<p>Şikayet yok.</p>'}`;
}

export function managementRoomRows(a,{esc,fmt}){return a.rooms.map(r=>`<tr><td>${esc(r.id)}</td><td>${r.closed?'Kapalı':'Açık'}</td><td>${r.players}</td><td>${r.spectators||0}</td><td>${Math.floor(r.timeLeft/60)}:${String(r.timeLeft%60).padStart(2,'0')}</td><td>${fmt(r.prize)}</td><td>${fmt(r.base_prize)}</td><td>${r.boost&&(!r.boost.until||r.boost.until>a.serverNow)?`Gold ×${r.boost.gold} · Yem ${r.boost.feedMs} ms · Bölünme ${r.boost.splitMs} ms${r.boost.until?` · ${Math.max(0,Math.ceil((r.boost.until-a.serverNow)/60000))} dk`:" · Süresiz"}`:"Normal"}</td></tr>`).join('')}
export function managementLive(a,{esc,fmt,form}){const metric=(title,n)=>`<div class="metric">${title}<strong>${fmt(n)}</strong></div>`;return `<div class="metric-row admin-metrics">${metric('Aktif oyuncu',a.stats.activePlayers)}${metric('İzleyici',a.stats.spectators)}${metric('Misafir',a.stats.guests)}${metric('Bağlantı',a.stats.online)}${metric('Dolu oda',a.stats.activeRooms)}${metric('Toplam hesap',a.stats.accounts)}</div><h3>Şu an bağlı oyuncular <small>· ${new Date(a.serverNow).toLocaleTimeString('tr-TR')}</small></h3><div class="admin-table-scroll"><table class="data-table"><thead><tr><th>HESAP</th><th>İSİM</th><th>ODA</th><th>DURUM</th><th>SKOR / REKOR</th><th>PARÇA</th><th>GOLD / BONUS</th><th>TAKIM / KLAN</th><th>PREMIUM</th><th>SON SİNYAL</th><th>İŞLEM</th></tr></thead><tbody>${a.livePlayers.map(p=>`<tr><td>${p.accountId?'#'+p.accountId:'Misafir'}</td><td>${esc(p.name)}</td><td>${esc(p.room)}</td><td>${p.spectator?'İzliyor':p.alive?'Oynuyor':'Ölü / menü'}${p.mutedUntil>a.serverNow?`<small class="danger-text">Sohbet banı · ${Math.ceil((p.mutedUntil-a.serverNow)/3600000)} saat kaldı</small>`:''}</td><td>${fmt(p.score)} / ${fmt(p.max)}</td><td>${p.cells}</td><td>${fmt(p.gold)} / ${fmt(p.bonus)}</td><td>${esc(p.team||'—')} / ${p.clanId?'#'+p.clanId:'—'}</td><td>${p.premium?'Var':'Yok'}</td><td>${Math.floor(p.lastPingAgoMs/1000)} sn önce</td><td>${p.accountId?form('mute','<input type="hidden" name="target" value="'+p.accountId+'"><label>Saat (0 = kaldır)<input aria-label="Sohbet banı süresi" type="number" name="hours" value="1" min="0" max="8760" required></label>','Sohbet banı','data-management="true"'):''}${form('kick','<input type="hidden" name="connection" value="'+esc(p.connection)+'">','Oyuncuyu at','data-management="true"')}</td></tr>`).join('')||'<tr><td colspan="11">Bağlı oyuncu yok.</td></tr>'}</tbody></table></div>`}
